fn scripted(
    required: Option<RequiredChecks>,
    readings: Vec<Vec<Check>>,
    after: Option<Vec<Vec<Check>>>,
    activity: Vec<ActivityAnswer>,
) -> MemoryHost {
    MemoryHost::seeded(HostState {
        required_checks: required,
        check_readings: BTreeMap::from([(first(), readings)]),
